containers=[
 {"Id":"abc123","Image":"nginx","Names":["/mycontainer"],"NetworkSettings":{"Networks":{"bridge":{"NetworkID":"n1","IPAddress":"172.17.0.2"},"customnet":{"NetworkID":"n2","IPAddress":"10.10.0.2"}}}},
 {"Id":"def456","Image":"redis","Names":["/other-1"],"NetworkSettings":{"Networks":{"bridge":{"NetworkID":"n1","IPAddress":"172.17.0.3"},"customnet":{"NetworkID":"n2","IPAddress":"172.18.0.3"}}}}
]
networks=[{"Name":"bridge","Id":"n1"},{"Name":"customnet","Id":"n2"}]
def handle(c):
    data=b""
    try:
        while b"\r\n\r\n" not in data:
            chunk=c.recv(4096)
            if not chunk: break
            data+=chunk
        req=data.decode(errors='ignore'); log.write(req.split("\r\n")[0]+"\n"); path=req.split(" ")[1] if data else ""
        if "containers/json" in path: body=json.dumps(containers).encode()
        elif "_ping" in path: body=b"OK"
        elif "networks" in path: body=json.dumps(networks).encode()
