	key := "<nil>"
	if ip != nil {
		key = ip.String()
	}
	for _, g := range p.Routes {
		if g.IPString() == key {
			for _, d := range g.Domains {
				if d == domain {
					return
				}
			}
			g.Domains = append(g.Domains, domain)
			return
		}
	}
	p.Routes = append(p.Routes, &RouteGroup{IP: ip, Domains: []string{domain}})
}

func (p *Profile) RouteCount() int {
	n := 0
	for _, g := range p.Routes {
		n += len(g.Domains)
	}
	return n
}

func (p *Profile) Clone() *Profile {
	np := &Profile{Name: p.Name, Status: p.Status}
	for _, g := range p.Routes {
		ng := &RouteGroup{IP: g.IP, Domains: append([]string(nil), g.Domains...)}
		np.Routes = append(np.Routes, ng)
	}
	return np
}

// MergeRoutes merges newProf routes into p following the behaviour
// observed from the reference tool: routes for IPs already present are
// added to the existing IP group; groups for new IPs are appended by
// iterating a map (which in Go yields a non-deterministic order for
// multiple new groups).
func (p *Profile) MergeRoutes(newProf *Profile) {
	if newProf == nil {
		return
	}
	newByIP := make(map[string]*RouteGroup)
	for _, g := range newProf.Routes {
		newByIP[g.IPString()] = g
	}
	for _, g := range p.Routes {
		if ng, ok := newByIP[g.IPString()]; ok {
			for _, d := range ng.Domains {
				found := false
				for _, ed := range g.Domains {
					if ed == d {
						found = true
						break
					}
				}
				if !found {
					g.Domains = append(g.Domains, d)
				}
			}
			delete(newByIP, g.IPString())
		}
	}
	for _, ng := range newByIP {
		npGroup := &RouteGroup{IP: ng.IP, Domains: append([]string(nil), ng.Domains...)}
		p.Routes = append(p.Routes, npGroup)
	}
}

func (p *Profile) RemoveDomain(domain string) {
	var groups []*RouteGroup
	for _, g := range p.Routes {
		var ds []string
		for _, d := range g.Domains {
			if d != domain {
				ds = append(ds, d)
			}
		}
		if len(ds) > 0 {
			g.Domains = ds
			groups = append(groups, g)
		}
	}
	p.Routes = groups
}

type defaultLine struct {
	Text      string
	IsRoute   bool
	Commented bool
	IP        string
	Host      string
}

type HostsFile struct {
	Path     string
	Defaults []defaultLine
	Profiles []*Profile
}

func parseProfileRouteLine(line string, prof *Profile) {
	trimmed := strings.TrimSpace(line)
	if trimmed == "" {
		return
	}
	fields := strings.Fields(trimmed)
	if len(fields) > 0 && fields[0] == "#" {
		fields = fields[1:]
	}
	if len(fields) < 2 {
		return
	}
	ip := net.ParseIP(fields[0])
	if ip == nil {
		return
	}
	for _, h := range fields[1:] {
		if strings.HasPrefix(h, "#") {
			break
		}
		prof.AddRoute(ip, h)
	}
}

// parseRoutesInto parses every line of a plain routes file (used for
// --from input) into prof.
func parseRoutesInto(lines []string, prof *Profile) {
	for _, line := range lines {
		parseProfileRouteLine(line, prof)
	}
}

func parseSingleDefaultRoute(raw string) (defaultLine, bool) {
	trimmed := strings.TrimSpace(raw)
	fields := strings.Fields(trimmed)
	if len(fields) > 0 && fields[0] == "#" {
		fields = fields[1:]
	}
	if len(fields) < 2 {
		return defaultLine{}, false
	}
	ip := net.ParseIP(fields[0])
	if ip == nil {
		return defaultLine{}, false
	}
	host := fields[1]
	if strings.HasPrefix(host, "#") {
		return defaultLine{}, false
	}
	commented := len(raw) > 0 && raw[0] == '#'
	ipStr := ip.String()
	text := ipStr + " " + host
	if commented {
		text = "# " + text
	}
	return defaultLine{Text: text, IsRoute: true, Commented: commented, IP: ipStr, Host: host}, true
}

func parseHostsData(path string, lines []string) *HostsFile {
	// Remove the banner (3 lines around the Content line).
	for i, line := range lines {
		if strings.Contains(line, bannerText) {
			if i == 0 {
				// Deliberately reproduce the reference behaviour:
				// this slicing panics with slice bounds out of range [:-1].
				lines = append(lines[:i-1], lines[i+2:]...)
			}
			newLines := make([]string, 0, len(lines))
			if i-1 > 0 {
				newLines = append(newLines, lines[:i-1]...)
			}
			// i-1 == 0 results in empty prefix (handled above by >0? fix below)
			if i-1 == 0 {
				newLines = newLines[:0]
			}
			if i+2 < len(lines) {
				newLines = append(newLines, lines[i+2:]...)
			} else if i+2 == len(lines) {
				// nothing after
			}
			// The construction above loses lines[:i-1] when i-1>0 due to
			// ordering; rebuild correctly:
			newLines = make([]string, 0, len(lines))
			newLines = append(newLines, lines[:i-1]...)
			if i+2 <= len(lines) {
				newLines = append(newLines, lines[i+2:]...)
			}
			lines = newLines
			break
		}
	}

	hf := &HostsFile{Path: path}
	var current *Profile
	inDefault := true
	addDefault := func(raw string) {
		trimmed := strings.TrimSpace(raw)
		if trimmed == "" {
			if len(hf.Defaults) > 0 && hf.Defaults[len(hf.Defaults)-1].Text == "" {
				return
			}
			hf.Defaults = append(hf.Defaults, defaultLine{Text: ""})
			return
		}
		if dl, ok := parseSingleDefaultRoute(raw); ok {
			hf.Defaults = append(hf.Defaults, dl)
		} else {
			hf.Defaults = append(hf.Defaults, defaultLine{Text: trimmed})
		}
	}

	for _, line := range lines {
		if m := profileHeaderRe.FindStringSubmatch(line); m != nil {
			status := m[1]
			name := strings.TrimSpace(m[2])
			if name == "" {
				p := &Profile{Name: "", Status: status}
				hf.Profiles = append(hf.Profiles, p)
				current = nil
				inDefault = true
				continue
			}
			if existing := hf.findProfile(name); existing != nil {
				existing.Status = status
				existing.Routes = nil
				hf.Profiles = append(hf.Profiles, existing)
				current = existing
			} else {
				p := &Profile{Name: name, Status: status}
				hf.Profiles = append(hf.Profiles, p)
				current = p
			}
			inDefault = false
			continue
		}
		if strings.Contains(strings.ToLower(line), "# end") {
			current = nil
			inDefault = true
			continue
		}
		if inDefault || current == nil {
			addDefault(line)
		} else {
			parseProfileRouteLine(line, current)
		}
	}
	return hf
}

func readLinesFromReader(scanner *bufio.Scanner) []string {
	var lines []string
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	return lines
}

func loadHostsFile() (*HostsFile, error) {
	f, err := os.Open(opts.hostFile)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	lines := readLinesFromReader(bufio.NewScanner(f))
	return parseHostsData(opts.hostFile, lines), nil
}

func (hf *HostsFile) reload() (*HostsFile, error) {
	return loadHostsFile()
}

func (hf *HostsFile) findProfile(name string) *Profile {
	for _, p := range hf.Profiles {
		if p.Name == name {
			return p
		}
	}
	return nil
}

func (hf *HostsFile) removeProfile(name string) {
	var out []*Profile
	for _, p := range hf.Profiles {
		if p.Name != name {
			out = append(out, p)
		}
	}
	hf.Profiles = out
}

func (hf *HostsFile) filteredProfiles(names []string) []*Profile {
	if len(names) == 0 {
		return nil
	}
	set := make(map[string]bool)
	for _, n := range names {
		set[n] = true
	}
	var out []*Profile
	for _, p := range hf.Profiles {
		if set[p.Name] {
			out = append(out, p)
		}
	}
	return out
}

func (hf *HostsFile) buildContent() string {
	var lines []string
	// default lines, trimming trailing blank lines
	defs := hf.Defaults
	for len(defs) > 0 && defs[len(defs)-1].Text == "" {
		defs = defs[:len(defs)-1]
	}
	for _, d := range defs {
		lines = append(lines, d.Text)
	}
	lines = append(lines, "")
	lines = append(lines, bannerHashes)
	lines = append(lines, bannerText)
	lines = append(lines, bannerHashes)
	for _, p := range hf.Profiles {
		lines = append(lines, "")
		lines = append(lines, fmt.Sprintf("# profile.%s %s", p.Status, p.Name))
		for _, g := range p.Routes {
			for _, d := range g.Domains {
				line := g.IPString() + " " + d
				if p.Status == "off" {
					line = "# " + line
				}
				lines = append(lines, line)
			}
		}
		lines = append(lines, "# end")
	}
	return strings.Join(lines, "\n") + "\n"
}

func (hf *HostsFile) flush() error {
	return os.WriteFile(hf.Path, []byte(hf.buildContent()), 0644)
}
EOF
gofmt -w hosts.go; echo ok"}

