package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"syscall"
	"unsafe"
)

var colorEnabled bool

func initColor() {
	colorEnabled = computeColor()
}

func computeColor() bool {
	if !isTerminal(os.Stdout) {
		return false
	}
	return strings.Contains(os.Getenv("TERM"), "xterm")
}

func isTerminal(f *os.File) bool {
	var termios [64]byte
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), uintptr(0x5401), uintptr(unsafe.Pointer(&termios[0])))
	return errno == 0
}

func coloredSymbol(sym string, code string) string {
	if colorEnabled {
		return "[\x1b[1;" + code + "m" + sym + "\x1b[0m]"
	}
	return "[" + sym + "]"
}

func infoSymbol() string  { return coloredSymbol("ℹ", "36") }
func successSymbol() string { return coloredSymbol("✔", "32") }
func errorSymbol() string { return coloredSymbol("✖", "31") }

func printInfoMessage(msg string) {
	if opts.quiet {
		return
	}
	fmt.Printf("%s %s\n\n", infoSymbol(), msg)
}

func printSuccessMessage(msg string) {
	if opts.quiet {
		return
	}
	fmt.Printf("%s %s\n\n", successSymbol(), msg)
}

func printUsingHostsFile() {
	if opts.quiet {
		return
	}
	if opts.out == "json" {
		return
	}
	if opts.hostFile == defaultHostsPath() && os.Getenv("HOSTCTL_FILE") == "" {
		return
	}
	fmt.Printf("%s Using hosts file: %s\n\n", infoSymbol(), opts.hostFile)
}

// ---------- Rendering ----------

type Row struct {
	Profile string
	Status  string
	IP      string
	Host    string
}

type rowGroup struct {
	Rows []Row
}

func displayWidth(s string) int {
	w := 0
	for _, r := range s {
		if r >= 0x1100 && (r <= 0x115f || r == 0x2329 || r == 0x232a || (r >= 0x2e80 && r <= 0xa4cf) || (r >= 0xac00 && r <= 0xd7a3) || (r >= 0xf900 && r <= 0xfaff) || (r >= 0xfe30 && r <= 0xfe6f) || (r >= 0xff00 && r <= 0xff60) || (r >= 0xffe0 && r <= 0xffe6) || (r >= 0x20000 && r <= 0x2fffd) || (r >= 0x30000 && r <= 0x3fffd)) {
			w += 2
		} else {
			w++
		}
	}
	return w
}

func padRight(s string, width int) string {
	d := width - displayWidth(s)
	if d <= 0 {
		return s
	}
	return s + strings.Repeat(" ", d)
}

func padCenter(s string, width int) string {
	d := width - displayWidth(s)
	if d <= 0 {
		return s
	}
	left := d / 2
	right := d - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

func effectiveOut() string {
	if opts.raw {
		return "raw"
	}
	return opts.out
}

// renderGroups renders groups of rows (profiles). forceProfileStatus
// means columns are forced to profile,status (status command).
func renderGroups(groups []rowGroup, forceProfileStatus bool) string {
	// flat rows
	var flat []Row
	for _, g := range groups {
		flat = append(flat, g.Rows...)
	}
	outType := effectiveOut()
	if outType == "json" {
		if len(flat) == 0 {
			return "null\n"
		}
		b, _ := json.Marshal(flat)
		return string(b) + "\n"
	}
	if len(flat) == 0 {
		return ""
	}
	var cols []string
	if forceProfileStatus {
		cols = []string{"profile", "status"}
	} else if len(opts.columns) > 0 {
		cols = opts.columns
	} else {
		cols = []string{"profile", "status", "ip", "domain"}
	}
	headers := make([]string, len(cols))
	for i, c := range cols {
		headers[i] = strings.ToUpper(c)
	}
	// build cells per group
	type cellGroup struct {
		cells [][]string
	}
	var cgroups []cellGroup
	var allCells [][]string
	for _, g := range groups {
		cg := cellGroup{}
		for _, r := range g.Rows {
			var cells []string
			for _, c := range cols {
				switch c {
				case "profile":
					cells = append(cells, r.Profile)
				case "status":
					cells = append(cells, r.Status)
				case "ip":
					cells = append(cells, r.IP)
				case "domain":
					cells = append(cells, r.Host)
				}
			}
			cg.cells = append(cg.cells, cells)
			allCells = append(allCells, cells)
		}
		cgroups = append(cgroups, cg)
	}
	// if no row produces any cell, render nothing
	maxCells := 0
	for _, c := range allCells {
		if len(c) > maxCells {
			maxCells = len(c)
		}
	}
	if maxCells == 0 {
		return ""
	}
	// widths
	widths := make([]int, len(headers))
	for i, h := range headers {
		widths[i] = displayWidth(h)
	}
	for _, cells := range allCells {
		for i, cell := range cells {
			if i < len(widths) && displayWidth(cell) > widths[i] {
				widths[i] = displayWidth(cell)
			}
		}
	}

	switch outType {
	case "raw":
		var sb strings.Builder
		// header
		for i, h := range headers {
			if i == len(headers)-1 {
				sb.WriteString(padRight(h, widths[i]+1))
			} else {
				sb.WriteString(padRight(h, widths[i]))
				sb.WriteString("\t")
			}
		}
		sb.WriteString("\n")
		for _, cg := range cgroups {
			for _, cells := range cg.cells {
				for _, cell := range cells {
					// find index of this cell to pad: need index loop
					_ = cell
				}
				for idx, cell := range cells {
					sb.WriteString(padRight(cell, widths[idx]))
					sb.WriteString("\t")
				}
				sb.WriteString("\n")
			}
		}
		return sb.String()
	case "markdown":
		borderParts := make([]string, len(headers))
		for i, w := range widths {
			borderParts[i] = strings.Repeat("-", w+2)
		}
		sep := "|" + strings.Join(borderParts, "|") + "|"
		var sb strings.Builder
		// header
		sb.WriteString(headerLine(headers, widths))
		sb.WriteString(sep + "\n")
		// groups with rows
		var nonEmpty []cellGroup
		for _, cg := range cgroups {
			if len(cg.cells) > 0 {
				nonEmpty = append(nonEmpty, cg)
			}
		}
		for gi, cg := range nonEmpty {
			for _, cells := range cg.cells {
				sb.WriteString(rowLine(cells, widths))
			}
			if gi < len(nonEmpty)-1 {
				sb.WriteString(sep + "\n")
			}
		}
		return sb.String()
	default: // table
		borderParts := make([]string, len(headers))
		for i, w := range widths {
			borderParts[i] = strings.Repeat("-", w+2)
		}
		border := "+" + strings.Join(borderParts, "+") + "+"
		var sb strings.Builder
		sb.WriteString(border + "\n")
		sb.WriteString(headerLine(headers, widths))
		sb.WriteString(border + "\n")
		for _, cg := range cgroups {
			if len(cg.cells) == 0 {
				continue
			}
			for _, cells := range cg.cells {
				sb.WriteString(rowLine(cells, widths))
			}
			sb.WriteString(border + "\n")
		}
		return sb.String()
	}
}

func headerLine(headers []string, widths []int) string {
	parts := make([]string, len(headers))
	for i, h := range headers {
		parts[i] = " " + padCenter(h, widths[i]) + " "
	}
	return "|" + strings.Join(parts, "|") + "|\n"
}

func rowLine(cells []string, widths []int) string {
	if len(cells) == 0 {
		return ""
	}
	parts := make([]string, len(cells))
	for i, cell := range cells {
		parts[i] = " " + padRight(cell, widths[i]) + " "
	}
	return "|" + strings.Join(parts, "|") + "|\n"
}

// profilesToGroups converts profiles plus optional default rows to groups.
func defaultRows(hf *HostsFile) []Row {
	var rows []Row
	for _, d := range hf.Defaults {
		if !d.IsRoute {
			continue
		}
		st := "on"
		if d.Commented {
			st = "off"
		}
		rows = append(rows, Row{Profile: "default", Status: st, IP: d.IP, Host: d.Host})
	}
	return rows
}

func profileRows(p *Profile) []Row {
	var rows []Row
	for _, g := range p.Routes {
		for _, d := range g.Domains {
			rows = append(rows, Row{Profile: p.Name, Status: p.Status, IP: g.IPString(), Host: d})
		}
	}
	return rows
}

func groupsForProfiles(profiles []*Profile) []rowGroup {
	var groups []rowGroup
	for _, p := range profiles {
		groups = append(groups, rowGroup{Rows: profileRows(p)})
	}
	return groups
}

// groupsForAll returns groups for default + all profiles of hf, filtered by names if provided.
func groupsForCandidates(hf *HostsFile, candidates []*Profile, includeDefault bool, filterNames []string) []rowGroup {
	var groups []rowGroup
	hasFilter := len(filterNames) > 0
	set := make(map[string]bool)
	for _, n := range filterNames {
		set[n] = true
	}
	if includeDefault {
		if !hasFilter || set["default"] {
			groups = append(groups, rowGroup{Rows: defaultRows(hf)})
		}
	}
	_ = candidates
	return groups
}

func allGroups(hf *HostsFile, filterNames []string) []rowGroup {
	var groups []rowGroup
	hasFilter := len(filterNames) > 0
	set := make(map[string]bool)
	for _, n := range filterNames {
		set[n] = true
	}
	if !hasFilter || set["default"] {
		groups = append(groups, rowGroup{Rows: defaultRows(hf)})
	}
	for _, p := range hf.Profiles {
		if hasFilter && !set[p.Name] {
			continue
		}
		groups = append(groups, rowGroup{Rows: profileRows(p)})
	}
	return groups
}

func enabledGroups(hf *HostsFile, filterNames []string) []rowGroup {
	return statusFilteredGroups(hf, "on", filterNames)
}
func disabledGroups(hf *HostsFile, filterNames []string) []rowGroup {
	return statusFilteredGroups(hf, "off", filterNames)
}
func statusFilteredGroups(hf *HostsFile, status string, filterNames []string) []rowGroup {
	var groups []rowGroup
	hasFilter := len(filterNames) > 0
	set := make(map[string]bool)
	for _, n := range filterNames {
		set[n] = true
	}
	if !hasFilter || set["default"] {
		groups = append(groups, rowGroup{Rows: defaultRows(hf)})
	}
	for _, p := range hf.Profiles {
		if p.Status != status {
			continue
		}
		if hasFilter && !set[p.Name] {
			continue
		}
		groups = append(groups, rowGroup{Rows: profileRows(p)})
	}
	return groups
}

func profilesGroupsFiltered(hf *HostsFile, filterNames []string) []rowGroup {
	var groups []rowGroup
	set := make(map[string]bool)
	for _, n := range filterNames {
		set[n] = true
	}
	for _, p := range hf.Profiles {
		if !set[p.Name] {
			continue
		}
		groups = append(groups, rowGroup{Rows: profileRows(p)})
	}
	return groups
}

// output helpers following per-command printing conventions
func printRendered(rendered string, println bool, suppressQuiet bool) {
	if suppressQuiet && opts.quiet {
		return
	}
	if println {
		fmt.Println(rendered)
	} else {
		fmt.Print(rendered)
	}
}
