package docker

import (
	"fmt"
	"path/filepath"
	"strings"

	"hostctl/pkg/types"

	"gopkg.in/yaml.v3"
)

type composeData struct {
	Services map[string]composeService `yaml:"services"`
}

type composeService struct {
	ContainerName string `yaml:"container_name"`
}

func ParseCompose(content []byte) (composeData, error) {
	var data composeData
	if err := yaml.Unmarshal(content, &data); err != nil {
		return data, fmt.Errorf("error parsing docker-compose content: %w", err)
	}
	return data, nil
}

// ProjectName derives the compose project name from the compose file
// path unless an explicit name is given.
func ProjectName(composeFilePath string, explicit string) string {
	if explicit != "" {
		return explicit
	}
	dir := filepath.Base(filepath.Dir(composeFilePath))
	var b strings.Builder
	for _, r := range strings.ToLower(dir) {
		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '-' {
			b.WriteRune(r)
		}
	}
	return b.String()
}

func RoutesFromCompose(containers []types.Container, data composeData, project string, domainSuffix string, keepPrefix bool, resolvedNetworkID string) []Route {
	var searchNames []string
	for svcName, svc := range data.Services {
		if svc.ContainerName != "" {
			searchNames = append(searchNames, svc.ContainerName)
		} else {
			searchNames = append(searchNames, project+"_"+svcName)
		}
	}
	var routes []Route
	for _, cont := range containers {
		name := strings.ReplaceAll(cont.Names[0], "/", "")
		matched := false
		for _, s := range searchNames {
			if strings.Contains(name, s) {
				matched = true
				break
			}
		}
		if !matched {
			continue
		}
		if cont.NetworkSettings == nil {
			continue
		}
		for _, endpoint := range cont.NetworkSettings.Networks {
			if resolvedNetworkID != "" && endpoint.NetworkID != resolvedNetworkID {
				continue
			}
			domainBase := name
			if !keepPrefix {
				domainBase = strings.Replace(name, project+"_", "", 1)
			}
			routes = append(routes, Route{IP: endpoint.IPAddress, Domain: domainBase + "." + domainSuffix})
		}
	}
	return routes
}
EOF
