var errDefaultProfile = errors.New("'default' profile should not be handled by hostctl")
var errMissingProfile = errors.New("missing profile name")
var errSpecifyOne = errors.New("specify only one profile")
var errUnknownProfile = errors.New("unknown profile name")

func validateSingleProfile(cmd *cobra.Command, args []string) error {
	if len(args) == 0 {
		return errMissingProfile
	}
	if len(args) > 1 {
		return errSpecifyOne
	}
	if args[0] == "default" {
		return errDefaultProfile
	}
	return nil
}

func validateProfileList(cmd *cobra.Command, args []string) error {
	all, _ := cmd.Flags().GetBool("all")
	if all {
		if len(args) > 0 {
			return errors.New("args must be empty with --all flag")
		}
		return nil
	}
	if len(args) == 0 {
		return errMissingProfile
	}
	for _, a := range args {
		if a == "default" {
			return errDefaultProfile
		}
	}
	return nil
}

func validateToggle(cmd *cobra.Command, args []string) error {
	if len(args) == 0 {
		return errMissingProfile
	}
	for _, a := range args {
		if a == "default" {
			return errDefaultProfile
		}
	}
	return nil
}

func validateDomains(cmd *cobra.Command, args []string) error {
	if len(args) == 0 {
		return errMissingProfile
	}
	for _, a := range args {
		if a == "default" {
			return errDefaultProfile
		}
	}
	return nil
}

// ---------------- core operations (load, mutate, flush, reload, print) ----------------

func profileRenderGroups(hf *HostsFile, p *Profile) []rowGroup {
	if p == nil {
		return []rowGroup{{Rows: nil}}
	}
	return []rowGroup{{Rows: profileRows(p)}}
}

func doEnableDisable(enable bool, args []string, all bool, only bool) error {
	hf, err := loadHostsFile()
	if err != nil {
		return err
	}
	target := "off"
	opposite := "on"
	if enable {
		target = "on"
		opposite = "off"
	}
	if all {
		for _, p := range hf.Profiles {
			p.Status = target
		}
	} else if only {
		set := make(map[string]bool)
		for _, a := range args {
			set[a] = true
		}
		for _, p := range hf.Profiles {
			if set[p.Name] {
				p.Status = target
			} else {
				p.Status = opposite
			}
		}
	} else {
		for _, a := range args {
			if hf.findProfile(a) == nil {
				return errUnknownProfile
			}
		}
		set := make(map[string]bool)
		for _, a := range args {
			set[a] = true
		}
		for _, p := range hf.Profiles {
			if set[p.Name] {
				p.Status = target
			}
		}
	}
	if err := hf.flush(); err != nil {
		return err
	}
	reloaded, err := loadHostsFile()
	if err != nil {
		return err
	}
	var groups []rowGroup
	if all {
		groups = allGroups(reloaded, nil)
	} else {
		groups = profilesGroupsFiltered(reloaded, args)
	}
	printRendered(renderGroups(groups, false), true, true)
	return nil
}

func doToggle(args []string) error {
	hf, err := loadHostsFile()
	if err != nil {
		return err
	}
	for _, a := range args {
		if hf.findProfile(a) == nil {
			return errUnknownProfile
		}
	}
	for _, a := range args {
		p := hf.findProfile(a)
		if p.Status == "on" {
			p.Status = "off"
		} else {
			p.Status = "on"
		}
	}
	if err := hf.flush(); err != nil {
		return err
	}
	reloaded, err := loadHostsFile()
	if err != nil {
		return err
	}
	printRendered(renderGroups(profilesGroupsFiltered(reloaded, args), false), true, true)
	return nil
}

func doRemoveProfiles(args []string, all bool) error {
	hf, err := loadHostsFile()
	if err != nil {
		return err
	}
	var names []string
	if all {
		if len(hf.Profiles) == 0 {
			return errors.New("there are no profiles")
		}
		for _, p := range hf.Profiles {
			names = append(names, p.Name)
		}
		hf.Profiles = nil
	} else {
		names = args
		for _, a := range args {
			if hf.findProfile(a) == nil {
				return errUnknownProfile
			}
			hf.removeProfile(a)
		}
	}
	if err := hf.flush(); err != nil {
		return err
	}
	printSuccessMessage(fmt.Sprintf("Profile(s) '%s' removed.", strings.Join(names, ", ")))
	printRendered("", true, true)
	return nil
}

func doAddDomains(profileName string, domains []string, ipStr string, wait time.Duration) error {
	hf, err := loadHostsFile()
	if err != nil {
		return err
	}
	p := hf.findProfile(profileName)
	if p == nil {
		p = &Profile{Name: profileName, Status: "on"}
		hf.Profiles = append(hf.Profiles, p)
	}
	ip := net.ParseIP(ipStr)
	for _, d := range domains {
		p.AddRoute(ip, d)
	}
	if err := hf.flush(); err != nil {
		return err
	}
	reloaded, err := loadHostsFile()
	if err != nil {
		return err
	}
	printSuccessMessage(fmt.Sprintf("Domains '%s' added.", strings.Join(domains, ", ")))
	var rp *Profile
	if reloaded != nil {
		rp = reloaded.findProfile(profileName)
	}
	printRendered(renderGroups(profileRenderGroups(reloaded, rp), false), true, true)
	return nil
}

func doRemoveDomains(profileName string, domains []string) error {
	hf, err := loadHostsFile()
	if err != nil {
		return err
	}
	p := hf.findProfile(profileName)
	if p == nil {
		return errUnknownProfile
	}
	for _, d := range domains {
		p.RemoveDomain(d)
	}
	removed := p.RouteCount() == 0
	if removed {
		hf.removeProfile(profileName)
	}
	if err := hf.flush(); err != nil {
		return err
	}
	reloaded, err := loadHostsFile()
	if err != nil {
		return err
	}
	if removed {
		printSuccessMessage(fmt.Sprintf("Profile '%s' removed.", profileName))
		printRendered(renderGroups([]rowGroup{{Rows: nil}}, false), false, true)
		return nil
	}
	printSuccessMessage(fmt.Sprintf("Domains '%s' removed.", strings.Join(domains, ", ")))
	rp := reloaded.findProfile(profileName)
	printRendered(renderGroups(profileRenderGroups(reloaded, rp), false), false, true)
	return nil
}

func readInputProfile(name string, from string) (*Profile, error) {
	prof := &Profile{Name: name, Status: "on"}
	var lines []string
	stat, _ := os.Stdin.Stat()
	if stat != nil && (stat.Mode()&os.ModeCharDevice) == 0 {
		scanner := makeScanner(os.Stdin)
		lines = readLinesFromReader(scanner)
	} else {
		f, err := os.Open(from)
		if err != nil {
			return nil, err
		}
		defer f.Close()
		lines = readLinesFromReader(makeScanner(f))
	}
	parseRoutesInto(lines, prof)
	return prof, nil
}

func doAddFromInput(name string, from string, replace bool) error {
	inputProf, err := readInputProfile(name, from)
	if err != nil {
		return err
	}
	hf, err := loadHostsFile()
	if err != nil {
		return err
	}
	if replace {
		hf.removeProfile(name)
		hf.Profiles = append(hf.Profiles, inputProf)
	} else {
		if existing := hf.findProfile(name); existing != nil {
			existing.MergeRoutes(inputProf)
		} else {
			hf.Profiles = append(hf.Profiles, inputProf)
		}
	}
	if err := hf.flush(); err != nil {
		return err
	}
	reloaded, err := loadHostsFile()
	if err != nil {
		return err
	}
	rp := reloaded.findProfile(name)
	if replace {
		printRendered(renderGroups(profileRenderGroups(reloaded, rp), false), false, true)
	} else {
		printRendered(renderGroups(profileRenderGroups(reloaded, rp), false), true, true)
	}
	return nil
}

func doReplaceProfileWithRoutes(name string, routes []docker.Route) error {
	hf, err := loadHostsFile()
	if err != nil {
		return err
	}
	prof := &Profile{Name: name, Status: "on"}
	for _, r := range routes {
		prof.AddRoute(net.ParseIP(r.IP), r.Domain)
	}
	hf.removeProfile(name)
	hf.Profiles = append(hf.Profiles, prof)
	if err := hf.flush(); err != nil {
		return err
	}
	reloaded, err := loadHostsFile()
	if err != nil {
		return err
	}
	rp := reloaded.findProfile(name)
	printRendered(renderGroups(profileRenderGroups(reloaded, rp), false), true, true)
	return nil
}

func copyFile(src string, dst string) error {
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()
	out, err := os.Create(dst)
	if err != nil {
		return err
	}
	defer out.Close()
	_, err = io.Copy(out, in)
	return err
}

// ---------------- wait handling ----------------

func handleWait(waitDur time.Duration, revertDesc string, waitArgs []string, revert func() error) error {
	if waitDur < 0 {
		return nil
	}
	if !opts.quiet {
		var msg string
		if waitDur == 0 {
			msg = fmt.Sprintf("Waiting until ctrl+c to %s from profile '%s'", revertDesc, strings.Join(waitArgs, ", "))
		} else {
			msg = fmt.Sprintf("Waiting for %s or ctrl+c to %s from profile '%s'", waitDur.String(), revertDesc, strings.Join(waitArgs, ", "))
		}
		printInfoMessage(msg)
	}
	waitForSignalOrTimeout(waitDur)
	if opts.quiet {
		fmt.Println()
	} else {
		fmt.Print("\n\n")
	}
	return revert()
}

