		Use:   "docker-compose [profile] [flags]",
		Short: "Sync your docker-compose containers IPs with a profile.",
		Long:  "\nReads from a docker-compose.yml file  the list of containers and add names and IPs to a profile in your hosts file.",
		Args:  validateSingleProfile,
		RunE: func(cmd *cobra.Command, args []string) error {
			composePath := composeFile
			if composePath == "" {
				cwd, err := os.Getwd()
				if err != nil {
					return err
				}
				composePath = filepath.Join(cwd, "docker-compose.yml")
			}
			f, err := os.Open(composePath)
			if err != nil {
				return err
			}
			defer f.Close()
			client, err := docker.NewClient()
			if err != nil {
				return err
			}
			containers, resolved, err := client.ListContainers(composeNetwork)
			if err != nil {
				return err
			}
			content, err := io.ReadAll(f)
			if err != nil {
				return err
			}
			data, err := docker.ParseCompose(content)
			if err != nil {
				return err
			}
			project := docker.ProjectName(composePath, composeProject)
			routes := docker.RoutesFromCompose(containers, data, project, composeDomain, composePrefix, resolved)
