import pathlib
p=pathlib.Path("hosts.go")
t=p.read_text()
start=t.index("func parseHostsData(path string, lines []string) *HostsFile {")
end=t.index("func readLinesFromReader")
new='''func parseHostsData(path string, lines []string) *HostsFile {
	hf := &HostsFile{Path: path}
	var current *Profile
	inProfile := false
	skipNext := false

	addRawDefault := func(raw string) {
		trimmed := strings.TrimSpace(raw)
		if trimmed == "" {
			if len(hf.Defaults) > 0 && hf.Defaults[len(hf.Defaults)-1].Text == "" {
				return
			}
			hf.Defaults = append(hf.Defaults, defaultLine{Text: ""})
			return
		}
		hf.Defaults = append(hf.Defaults, defaultLine{Text: trimmed})
	}

	for _, line := range lines {
		if skipNext {
			skipNext = false
			continue
		}
		if m := profileHeaderRe.FindStringSubmatch(line); m != nil {
			status := m[1]
			name := strings.TrimSpace(m[2])
			if name == "" {
				p := &Profile{Name: "", Status: status}
				hf.Profiles = append(hf.Profiles, p)
				current = nil
				inProfile = false
				continue
			}
			if existing := hf.findProfile(name); existing != nil {
				existing.Status = status
				existing.Routes = nil
				hf.Profiles = append(hf.Profiles, existing)
				current = existing
			} else {
				p := &Profile{Name: name, Status: status}
				hf.Profiles = append(hf.Profiles, p)
				current = p
			}
			inProfile = true
			continue
		}
		if strings.Contains(strings.ToLower(line), "# end") {
			current = nil
			inProfile = false
			continue
		}
		if inProfile {
			parseProfileRouteLine(line, current)
			continue
		}
		// Default section.
		if dl, ok := parseSingleDefaultRoute(line); ok {
			hf.Defaults = append(hf.Defaults, dl)
			continue
		}
		if strings.Contains(line, bannerText) {
			// Remove the previously stored default line (the banner
			// hash line in well-formed files). This deliberately
			// mirrors the reference behaviour when there is no
			// previous line: it panics with slice bounds out of
			// range [:-1].
			hf.Defaults = hf.Defaults[:len(hf.Defaults)-1]
			skipNext = true
			continue
		}
		addRawDefault(line)
	}
	return hf
}

'''
